import {combatStats,enemyStats,SKILLS,Pool,clamp} from './core.js';
import {hero,enemy,ellipse,HERO_SCENE_ART,placeSceneHero} from './art.js';
import {drawArenaHero} from './action-art.js';
export class Battle{
constructor(player,stage,feedback,survival=false){this.player=player;this.stage=stage;this.survival=survival;this.wavesCleared=0;this.wave=0;this.stats=combatStats(player);this.hp=this.stats.hp;this.foe=enemyStats(stage,0);this.enemyHp=this.foe.hp;this.time=0;this.nextTurn=1;this.turn=0;this.attacks=0;this.done=false;this.won=false;this.rewarded=false;this.event=0;this.heroAttack=0;this.normalAttackAt=-Infinity;this.enemyAttack=0;this.heroHit=0;this.enemyHit=0;this.ward=0;this.cooldowns={flare:0,ward:0,mend:0,tonic:0};this.effects=new Pool(30);this.feedback=feedback;this.message='Attacks are automatic. Watch for a golden opening.'}
step(dt){if(this.done)return;this.time+=dt;this.heroAttack=Math.max(0,this.heroAttack-dt*3);this.enemyAttack=Math.max(0,this.enemyAttack-dt*3);this.heroHit=Math.max(0,this.heroHit-dt*3);this.enemyHit=Math.max(0,this.enemyHit-dt*3);this.event=Math.max(0,this.event-dt);for(const k of Object.keys(this.cooldowns))this.cooldowns[k]=Math.max(0,this.cooldowns[k]-dt);for(const e of this.effects.items){if(!e.active)continue;e.life-=dt;e.y-=40*dt;if(e.life<=0)e.active=false}if(this.time>=this.nextTurn){this.nextTurn=this.time+1.05;if(this.turn%2===0){this.attacks++;this.heroAttack=1;this.normalAttackAt=this.time;if(Math.random()<this.stats.hit){const crit=Math.random()<this.stats.crit;this.damageEnemy(Math.round(this.stats.attack*(crit?1.7:1)),crit?'CRITICAL!':'');if(!this.done&&this.attacks%3===0){this.event=1.3;this.message='An opening! Tap the golden burst.'}}else{this.pop(980,275,'MISS','#e6e7cd');this.message='Your strike missed. Accuracy training improves hit chance.'}}else{this.enemyAttack=1;if(Math.random()<this.stats.dodge){this.pop(410,275,'DODGE','#99f0cf');this.message='A clean dodge!'}else{const blocked=Math.random()<this.stats.block;const amount=Math.max(1,Math.round(this.foe.attack*(blocked?.5:1)*(this.ward>0?.5:1)));if(this.ward>0)this.ward--;this.hp=Math.max(0,this.hp-amount);this.heroHit=1;this.pop(410,275,(blocked?'BLOCK ':'−')+amount,blocked?'#a6eacf':'#ffb5a0');this.feedback('miss');if(this.hp<=0){this.done=true;this.won=false;this.event=0}}}this.turn++}}
pop(x,y,text,color){this.effects.spawn({x,y,text,color,life:1})}
damageEnemy(amount,label=''){if(this.done)return;this.enemyHp=Math.max(0,this.enemyHp-amount);this.enemyHit=1;this.pop(980,275,label?label+' −'+amount:'−'+amount,label?'#ffe397':'#fff8d6');this.feedback('hit');if(this.enemyHp===0){this.wavesCleared++;this.event=0;if(this.wave>=2&&!this.survival){this.done=true;this.won=true;return}this.wave++;this.foe=enemyStats(this.stage,this.wave%3,this.survival?this.wave:0);this.enemyHp=this.foe.hp;this.nextTurn=this.time+1.8;this.message=this.survival?'Wave '+(this.wave+1)+' · '+this.wavesCleared*15+' coins banked':'Wave '+(this.wave+1)+' of 3';this.turn=1}}
input(action){if(this.done)return false;if(action==='event'){if(this.event<=0)return false;this.event=0;this.heroAttack=1;this.damageEnemy(Math.round(this.stats.attack*1.25),'PERFECT');return true}if(action==='tonic'){if(this.player.potions<=0||this.cooldowns.tonic>0||this.hp>=this.stats.hp)return false;this.player.potions--;this.hp=Math.min(this.stats.hp,this.hp+Math.round(this.stats.hp*.45));this.cooldowns.tonic=10;this.pop(410,275,'+45% HP','#a1edbf');this.feedback('heal');return true}if(!this.player.skills.includes(action)||!SKILLS[action]||this.cooldowns[action]>0)return false;if(action==='mend'&&this.hp>=this.stats.hp)return false;this.cooldowns[action]=SKILLS[action].cooldown;if(action==='flare'){this.heroAttack=1;this.damageEnemy(Math.round(this.stats.attack*2.5),'SUNFLARE')}if(action==='ward'){this.ward=3;this.pop(410,275,'GUARDED','#a2e8e5');this.feedback('heal')}if(action==='mend'){this.hp=Math.min(this.stats.hp,this.hp+Math.round(this.stats.hp*.3));this.pop(410,275,'+30% HP','#a1edbf');this.feedback('heal')}return true}
draw(c,t){c.save();placeSceneHero(c,410,500,HERO_SCENE_ART.arenaScale);c.translate(-410,-500);if(!drawArenaHero(c,this))hero(c,410,500,1.65,this.player.equipment,t,this.heroAttack,this.heroHit,this.player.scarf);if(this.ward>0){c.strokeStyle='#9cf4e6aa';c.lineWidth=5;c.beginPath();c.ellipse(430,375,95,145,0,-1.5,1.5);c.stroke()}c.restore();enemy(c,980-this.enemyAttack*26,495,1.8,this.foe.type,t,this.enemyHit);for(const e of this.effects.items){if(!e.active)continue;c.globalAlpha=clamp(e.life,0,1);c.font='700 28px "DM Sans",sans-serif';c.textAlign='center';c.strokeStyle='#224350';c.lineWidth=5;const y=e.y-(e.x===410?158*1.65*(HERO_SCENE_ART.arenaScale-1):0);c.strokeText(e.text,e.x,y);c.fillStyle=e.color;c.fillText(e.text,e.x,y)}c.globalAlpha=1}
}
